INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(18667, 0, 0, 'koKR', 'Wszelkie ciało musi spłonąć.'),
(18667, 0, 1, 'koKR', 'Całe stworzenie musi zostać unicestwione!'),
(18667, 0, 2, 'koKR', 'Moc będzie wasza!'),
(18667, 1, 2, 'koKR', 'Widzę umarlaków! Wszędzie umarlaki!'),
(18667, 3, 0, 'koKR', 'Pomóc nam, szybko!'),
(18667, 5, 0, 'koKR', 'Być gotowi na powrót Mrocznego.'),
(18667, 5, 1, 'koKR', 'Żeby my mieć miejsce w nowym wszechświecie.'),
(18667, 5, 2, 'koKR', 'Mroczny obiecać!'),
(18667, 6, 2, 'koKR', 'Wy być umarlaki!'),
(18667, 8, 0, 'koKR', 'Pomóc nam, szybko!'),
(18667, 9, 0, 'koKR', 'Arrgh, aah...ahhh'),
(18731, 0, 0, 'koKR', 'Niewierni wtargnęli do sanktuarium! Żałosne szkodniki... Jeszcze nie poznaliście prawdziwego znaczenia męki!'),
(18732, 0, 0, 'koKR', 'Skupcie umysły, bo dni rozrachunku są bliskie. Wkrótce niszczyciel światów powróci, by dotrzymać obietnicy. Wkrótce rozpocznie się zagłada wszystkiego, co istnieje!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(16259, 'koKR', '', '%s wykonuje dziwne gesty.', 0),
(16271, 'koKR', '', '%s zaczyna przyzywać zaprzysiężonego kabalistów!', 0),
(16275, 'koKR', '', '%s zaczyna przyzywać akolitę kabalistów!', 0),
(16278, 'koKR', '', '%s przyzywa na pomoc akolitę kabalistów!', 0),
(16280, 'koKR', '', '%s przyzywa na pomoc zaprzysiężonego kabalistów!', 0),
(16433, 'koKR', 'Pora na zabawę!', '', 0),
(16915, 'koKR', 'Dawno temu, w wymiarze kosmosu niepojętym dla śmiertelnych umysłów, narodziła się – jeśli można tak to nazwać – istota o tak niewyobrażalnej mocy, że samo jej pojawienie się roztrzaskało całą otaczającą ją rzeczywistość.$B$BZnana jedynie jako Szmer, była esencją dźwięku, a kto usłyszał jej mowę, ten poznawał wieczną śmierć!', '', 0),
(16928, 'koKR', '<Czytaj dalej, jeśli się odważysz...>', '<Czytaj dalej, jeśli się odważysz...>', 0),
(16930, 'koKR', 'Istniała wyłącznie dla chaosu, a jej najcichszy szept oznaczał zagładę całych światów!$B$BMimo to znaleźli się tacy, którzy próbowali czcić tę bezrozumną istotę. Byli nawet tacy, jeszcze bardziej szaleni, którzy ważyli się myśleć, że zdołają ją kontrolować.', '', 0),
(16936, 'koKR', 'Stęchłe stronice kodeksu zdają się same, jak za sprawą magii, przewracać, kierując twoją uwagę ku konkretnemu rozdziałowi, za okropnościami, których żadne śmiertelne oczy nie powinny nigdy ujrzeć.$B$BKsięga otwiera się na stronie, która w niepojęty sposób wydaje się „właściwa”, a zarazem tak bardzo zła.', '', 0),
(16937, 'koKR', 'I oto możni padali drżący u jej stóp, w strachu, że skieruje ku nim swe słowa.$B$BA jednak ci szarlatani, ci pozorni wyznawcy nieistniejącej religii, wciąż buntowali się przeciw nieuniknionemu w daremnej próbie zapanowania nad swym „bogiem”. Obojętny i zapewne nawet ich niedostrzegający Szmer ziewnął, a oni poznali niebyt.$B$BJednemu jednak jakimś cudem udało się przetrwać i w swym szaleństwie znalazł sposób, by sprowadzić Szmera na świat.', '', 0),
(16938, 'koKR', 'Ten śmiertelnik, władający wiedzą tajemną i mroczną, której nikt nie mógł prześcignąć, opracował metodę wzmocnienia przywołania poprzez chwytanie i wykorzystywanie niezliczonych dusz.$B$BZa sprawą jego urządzeń do zbierania dusz całe cywilizacje zostały doprowadzone do zagłady, by zasilić rytuał, za pomocą którego on i jego wspólnicy mieli sprowadzić Szmera do swojego świata.', '', 0),
(16939, 'koKR', 'I przywołali Szmera.$B$BUżyli potężnej magii więżącej i wyciszającej, podtrzymywanej przez nieustanny dopływ dusz. A jednak wciąż nie potrafili zapanować nad bestią ani nagiąć jej do swojej woli.$B$BŚmiertelnicy ci zaczęli obmyślać różne strategie, a każda kolejna zawodziła. Tym samym osłabiali rytuały i niechcący dali Szmerowi odrobinę swobody.$B$BTo wystarczyło.', '', 0),
(16940, 'koKR', 'Tylko ta księga przetrwała kataklizm, który zniszczył ich świat. Kataklizm sprowadzony przez dumnych i głupich ludzi, którzy myśleli, że zapanują nad kosmiczną istotą o niezmierzonej mocy.$B$BCzy ty, posiadaczu kodeksu, zrobisz to samo?$B$BCzy masz niezawodną metodę, by przywołać Szmera albo którąkolwiek z innych istot, o których z lękiem szepczą te nieświęte stronice?$B$BZobaczymy.', '', 0),
(17563, 'koKR', 'Pożałujesz!', '', 0),
(17569, 'koKR', 'To... nie... dobrze...', '', 0),
(17573, 'koKR', 'Dla ciebie nie ma powrotu!', '', 0),
(17575, 'koKR', 'Niezła próba.', '', 0),
(17576, 'koKR', 'Teraz ty zniknąć na zawsze!', '', 0),
(17577, 'koKR', 'Ty przegrać!', '', 0),
(17859, 'koKR', 'Pomóżcie mi, głupcy, zanim będzie za późno!', '', 0),
(17860, 'koKR', 'Żałośni śmiertelnicy! Drogo za to zapłacicie.', '', 0),
(17863, 'koKR', 'Nareszcie coś, co rozproszy nudę!', '', 0),
(17864, 'koKR', 'Boisz się śmierci?', '', 0),
(17865, 'koKR', 'To jest część, którą lubię najbardziej...', '', 0),
(17866, 'koKR', 'Nie... przeceniaj... swoich sił, śmiertelniku.', '', 0),
(17867, 'koKR', 'Przybądźcie mi na pomoc! Słuchajcie teraz swego pana!', '', 0),
(17868, 'koKR', 'Złożę ofiarę z twojej krwi!', '', 0),
(17869, 'koKR', 'Będziesz świetnym przykładem dla innych!', '', 0),
(17870, 'koKR', 'Dobrze, godna ofiara!', '', 0),
(17871, 'koKR', 'Służę z dumą.', '', 0),
(17872, 'koKR', 'Twoja śmierć służy wyższej sprawie...', '', 0),
(17873, 'koKR', 'Oddaję życie... z radością.', '', 0);
